```java
public class Account {
    private static int count;       // static field (shared)
    private final int id;           // instance field
    private double balance;

    static { count = 0; }           // static initializer block
    { balance = 0.0; }              // instance initializer block

    public Account(int id) {        // constructor
        this.id = id;
        count++;
    }

    public void deposit(double amt) { balance += amt; } // instance method
    public static int getCount() { return count; }       // static method

    static class Audit { }          // nested (static) class
}
```

```java
class Car {
    int speed;        // default 0 before constructor
    String model;     // default null before constructor
    Car() {
        // at this point speed == 0, model == null
        model = "Tesla"; // constructor sets the real value
    }
}

Car a = new Car();    // 'a' (stack) holds a reference to a heap object
System.out.println(a.model); // Tesla
```

```java
class Counter {
    static int total;     // shared across ALL objects
    Counter() { total++; }
}
Counter a = new Counter();
Counter b = new Counter();
System.out.println(a.total); // 2  (NOT 1) — there's only one 'total'
```

```java
class Counter {
    static int total;     // one shared copy (class-wide count)
    int id;               // one per object
    Counter() { id = ++total; }
}
Counter a = new Counter(); // a.id = 1
Counter b = new Counter(); // b.id = 2
System.out.println(Counter.total); // 2  (access via class name)
```

```java
class Box { int value; }

Box a = new Box(); a.value = 10;
Box b = a;                 // alias: same object
b.value = 50;

System.out.println(a.value); // 50  (changed via b)
System.out.println(a == b);  // true (same object/identity)

Box c = new Box(); c.value = 50; // separate object, equal value
System.out.println(a == c);  // false (different objects)
```

```java
class Cart {
    private final List<String> items;
    Cart(List<String> items) { this.items = items; } // stores the alias!
}
List<String> src = new ArrayList<>(List.of("book"));
Cart cart = new Cart(src);
src.add("hack"); // mutates the cart's internal list via the alias
```

```java
class Cart {
    private final List<String> items;
    Cart(List<String> items) { this.items = List.copyOf(items); } // own object
}
List<String> src = new ArrayList<>(List.of("book"));
Cart cart = new Cart(src);
src.add("hack"); // no effect — cart holds its own copy
```
